+import { $internal } from '../../common';
+import type { Entity } from '../../entity/types';
+import { getEntityId } from '../../entity/utils/pack-entity';
+import { isRelation } from '../../relation/utils/is-relation';
+import { getStore, hasTrait } from '../../trait/trait';
+import type { Trait } from '../../trait/types';
+import type { World } from '../../world';
+import { createModifier } from '../modifier';
+import type { Modifier, Predicate, PredicateData } from '../types';
+import { createTrackingId } from '../utils/tracking-cursor';
+
+/**
+ * Creates a value-based query predicate. Predicate dependencies are read in the
+ * supplied order and are deliberately omitted from query callback tuples.
+ */
+export function createPredicate<T extends Trait[]>(
+    dependencies: T,
+    predicate: (data: PredicateData<T>) => boolean
+): Predicate<T> {
+    for (const dependency of dependencies) {
+        if (
+            isRelation(dependency as never) ||
+            dependency[$internal].type === 'tag' ||
+            dependency[$internal].relation
+        ) {
+            throw new Error('Predicate dependencies must be data traits, not tags or relations.');
+        }
+    }
+
+    const id = createTrackingId();
+    return Object.assign(createModifier(`predicate-${id}`, id, dependencies), { predicate }) as Predicate<T>;
+}
+
+export function matchesPredicate(world: World, entity: Entity, predicate: Predicate): boolean {
+    const values: unknown[] = [];
+    for (const dependency of predicate.traits) {
+        if (!hasTrait(world, entity, dependency)) return false;
+        values.push(dependency[$internal].get(getEntityId(entity), getStore(world, dependency)));
+    }
+    return predicate.predicate(values as never);
+}
+
+/** Re-evaluate only queries that depend on the changed data trait. */
+export function refreshPredicateQueries(world: World, entity: Entity, trait: Trait) {
+    const instance = world[$internal].traitInstances[trait.id];
+    if (!instance) return;
+    for (const query of instance.predicateQueries) query.refreshPredicate(world, entity);
+}
+
+export function createPredicateTrackingModifier(
+    type: 'added' | 'removed' | 'changed',
+    id: number,
+    predicate: Predicate
+): Modifier {
+    return Object.assign(createModifier(`${type}-${id}`, id, predicate.traits), {
+        predicates: [predicate],
+    });
+}
